from __future__ import annotations


PATHSPACE_EXTENSION = r"""
<style>
#view-pathspace>section{max-width:1500px;margin:0 auto}.pathspace-head{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.pathspace-head input{height:33px;border:1px solid #999;padding:0 9px;font:11px Consolas,monospace;min-width:260px}.pathspace-summary{display:grid;grid-template-columns:repeat(5,1fr);border-top:1px solid #c7c7c7;border-left:1px solid #c7c7c7;margin:12px 0}.pathspace-summary>div{padding:11px;border-right:1px solid #c7c7c7;border-bottom:1px solid #c7c7c7;min-height:70px}.pathspace-summary strong{display:block;font-size:17px;margin-top:5px}.pathspace-layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:14px}.pathspace-panel{border:1px solid #c7c7c7;padding:13px;min-width:0}.pathspace-targets{max-height:650px;overflow:auto}.pathspace-target{border-bottom:1px solid #ddd;padding:8px 0;cursor:pointer;font:10px/1.45 Consolas,monospace}.pathspace-target:hover{background:#f6f6f6}.pathspace-target b{display:block;font-size:11px}.pathspace-contract{border:1px solid #c7c7c7;padding:10px 12px;margin:12px 0;font-size:10px;line-height:1.55}.path-map{border:1px solid #c7c7c7;min-height:390px;overflow:auto;margin-bottom:14px}.path-map svg{display:block;width:100%;min-width:760px;height:390px}.path-node rect{fill:#fff;stroke:#111;stroke-width:1.2;rx:5;ry:5}.path-node text{fill:#111;font:10px Consolas,monospace}.path-node .sub{fill:#666;font:8px Arial,sans-serif}.path-edge{stroke:#777;stroke-width:1.2;fill:none}.path-edge.hot{stroke:#111;stroke-width:2}.path-edge-label{font:8px Consolas,monospace;fill:#333}.path-boundary rect{stroke-dasharray:5 4}.pathspace-row{display:grid;grid-template-columns:85px 145px 110px minmax(150px,1fr) 80px 80px 90px 100px;gap:7px;border-bottom:1px solid #ddd;padding:8px 3px;font:10px/1.4 Consolas,monospace;align-items:start}.pathspace-row.head{font:700 9px Arial,Helvetica,sans-serif;text-transform:uppercase;letter-spacing:.08em;color:#666;position:sticky;top:0;background:#fff}.pathspace-rows{max-height:420px;overflow:auto}.pathspace-empty{padding:20px;color:#666;font-size:10px}.pathspace-anomaly{font-weight:700}.pathspace-truth{font:10px/1.5 Consolas,monospace;white-space:pre-wrap}.path-legend{font-size:9px;color:#666;line-height:1.5;margin-top:7px}
@media(max-width:1050px){.pathspace-layout{grid-template-columns:1fr}.pathspace-summary{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.pathspace-summary{grid-template-columns:1fr 1fr}.pathspace-row{grid-template-columns:1fr 1fr}}
</style>
<script>
(()=>{
const P=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current='',lastTargetsAt=0;
async function api(path){const response=await fetch(path,{cache:'no-store'});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||data));return data;}
function inject(){
  if(P('view-pathspace'))return;
  const nav=document.querySelector('nav'),main=document.querySelector('main'),topo=nav?.querySelector('button.tab[data-view="topology"]'),foot=main?.querySelector('.foot');if(!nav||!main)return;
  try{pages.pathspace=['Network Path Space','Packet-proven communication paths and the known Windows routing boundary.']}catch{}
  const button=document.createElement('button');button.className='tab';button.dataset.view='pathspace';button.textContent='Path Space';button.onclick=()=>{setView('pathspace');loadTargets();};if(topo?.nextSibling)nav.insertBefore(button,topo.nextSibling);else nav.appendChild(button);
  const view=document.createElement('div');view.className='view';view.id='view-pathspace';view.innerHTML=`<section><div class="sectionhead"><div><h2>Network Path Space</h2><div class="small">Select a real observed IP. MON shows only packet-proven peer relationships plus the configured Windows gateway boundary.</div></div><div class="pathspace-head"><input id="pathTarget" placeholder="Observed IP"><button class="btn" id="pathAnalyze">Analyze</button><button class="btn" id="pathInvestigate">Investigate</button><button class="btn" id="pathRefresh">Refresh</button></div></div><div class="pathspace-summary" id="pathSummary"></div><div class="pathspace-contract" id="pathContract">Select an observed target. No target, switch, router, or physical hop is invented.</div><div class="pathspace-layout"><aside class="pathspace-panel"><div class="label">Real Observed Targets</div><div class="pathspace-targets" id="pathTargets"><div class="pathspace-empty">Loading…</div></div></aside><div><div class="path-map" id="pathMap"><div class="pathspace-empty">Choose a target to build the communication map.</div></div><div class="pathspace-panel"><div class="label">Observed Relationships</div><div class="pathspace-rows" id="pathRows"><div class="pathspace-empty">No target selected.</div></div><div class="label" style="margin-top:14px">Truth / Boundary</div><div class="pathspace-truth" id="pathTruth">No path report loaded.</div></div></div></div><div class="path-legend">Solid link = current-session TShark packet relationship. Dashed gateway box = configured routing boundary only; MON does not claim it as a measured physical hop.</div></section>`;main.insertBefore(view,foot||null);
  P('pathAnalyze').onclick=()=>analyze(P('pathTarget').value);P('pathTarget').addEventListener('keydown',e=>{if(e.key==='Enter')analyze(e.currentTarget.value)});P('pathInvestigate').onclick=()=>{const target=P('pathTarget').value.trim();if(target&&typeof window.openInvestigation==='function')window.openInvestigation(target)};P('pathRefresh').onclick=()=>{loadTargets(true);if(current)analyze(current)};
  window.openPathSpace=target=>{target=String(target||'').trim();if(target)P('pathTarget').value=target;setView('pathspace');loadTargets();if(target)analyze(target);};
  loadTargets();
}
function summary(label,value){return`<div><div class="label">${esc(label)}</div><strong>${esc(value)}</strong></div>`}
async function loadTargets(force=false){if(!force&&Date.now()-lastTargetsAt<3000)return;try{const data=await api('/api/v1/operator/targets'),targets=data.targets||[];lastTargetsAt=Date.now();P('pathTargets').innerHTML=targets.map(item=>`<div class="pathspace-target" data-path-target="${esc(item.ip)}"><b>${esc(item.ip)}</b>${esc(item.classification||'OBSERVED_PACKET_PEER')} · ${Number(item.packets||0).toLocaleString()} packets<br>${esc(item.evidence||'PACKET')}</div>`).join('')||'<div class="pathspace-empty">No packet-observed targets yet.</div>';P('pathTargets').querySelectorAll('[data-path-target]').forEach(row=>row.onclick=()=>{const target=row.dataset.pathTarget||'';P('pathTarget').value=target;analyze(target)});}catch(error){P('pathTargets').innerHTML=`<div class="pathspace-empty">${esc(error.message)}</div>`}}
function classify(rel){const role=String(rel.peer_role||'').toUpperCase();return role.includes('LOCAL')||role.includes('SENSOR')||role.includes('INFRASTRUCTURE')||role.includes('GATEWAY')?'LOCAL':'EXTERNAL'}
function renderMap(data){const rels=(data.relationships||[]).slice(0,8),target=data.target||'',gateway=data.known_boundary||'',W=1000,H=390,targetX=125,targetY=195,boundaryX=480,boundaryY=195,peerX=830;if(!rels.length){P('pathMap').innerHTML='<div class="pathspace-empty">No packet-proven relationships for this observed target.</div>';return}const peerYs=rels.map((_,i)=>rels.length===1?195:55+i*(280/Math.max(1,rels.length-1)));let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Packet observed communication path map"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="#777"/></marker></defs>`;svg+=`<g class="path-node" transform="translate(${targetX},${targetY})"><rect x="-90" y="-30" width="180" height="60"></rect><text text-anchor="middle" y="-4">${esc(target)}</text><text class="sub" text-anchor="middle" y="14">OBSERVED TARGET</text></g>`;if(gateway){svg+=`<g class="path-node path-boundary" transform="translate(${boundaryX},${boundaryY})"><rect x="-95" y="-30" width="190" height="60"></rect><text text-anchor="middle" y="-4">${esc(gateway)}</text><text class="sub" text-anchor="middle" y="14">WINDOWS DEFAULT GATEWAY · CONTEXT</text></g>`;}rels.forEach((rel,i)=>{const y=peerYs[i],external=classify(rel)==='EXTERNAL',midX=external&&gateway?boundaryX:((targetX+peerX)/2),startX=targetX+90,endX=peerX-90,anoms=(rel.anomalies||[]).length,cls=anoms?'path-edge hot':'path-edge';if(external&&gateway){svg+=`<path class="${cls}" d="M${startX},${targetY} C300,${targetY} 350,${boundaryY} ${boundaryX-95},${boundaryY}" marker-end="url(#arrow)"></path><path class="${cls}" d="M${boundaryX+95},${boundaryY} C620,${boundaryY} 700,${y} ${endX},${y}" marker-end="url(#arrow)"></path>`;}else{svg+=`<path class="${cls}" d="M${startX},${targetY} C${midX},${targetY} ${midX},${y} ${endX},${y}" marker-end="url(#arrow)"></path>`;}svg+=`<text class="path-edge-label" x="${external&&gateway?650:470}" y="${Math.max(18,y-8)}">${esc(rel.protocol||'PACKET')} · ${Number(rel.packets||0).toLocaleString()} pkts${anoms?` · ${anoms} anomaly`:''}</text>`;svg+=`<g class="path-node" transform="translate(${peerX},${y})"><rect x="-90" y="-28" width="180" height="56"></rect><text text-anchor="middle" y="-3">${esc(rel.peer||'—')}</text><text class="sub" text-anchor="middle" y="14">${esc(rel.peer_role||classify(rel))}</text></g>`;});svg+='</svg>';P('pathMap').innerHTML=svg;}
async function analyze(target){target=String(target||'').trim();if(!target)return;current=target;P('pathRows').innerHTML='<div class="pathspace-empty">Building packet-evidence path report…</div>';P('pathMap').innerHTML='<div class="pathspace-empty">Building map…</div>';try{const data=await api(`/api/v1/pathspace/${encodeURIComponent(target)}`),truth=data.truth||{},rels=data.relationships||[];P('pathSummary').innerHTML=summary('Target',data.target||target)+summary('Evidence','TSHARK')+summary('Relationships',rels.length)+summary('Routing Boundary',data.known_boundary||'NONE')+summary('Physical Hops','NOT CLAIMED');P('pathContract').textContent=data.statement||'Current-session packet relationships only.';P('pathTruth').textContent=`observed=${Boolean(truth.observed)}\nlocal_scope=${Boolean(truth.local_scope)}\nconfirmed_local_asset=${Boolean(truth.confirmed_local_asset)}\nmonitor_host=${Boolean(truth.is_monitor_host)}\ngateway=${Boolean(truth.is_gateway)}\nknown_boundary=${data.known_boundary||'none'}\nboundary_meaning=${data.boundary_meaning||'none'}\nphysical_hops_verified=${Boolean(data.physical_hops_verified)}`;renderMap(data);if(!rels.length){P('pathRows').innerHTML='<div class="pathspace-empty">No packet-observed relationship for this target.</div>';return}P('pathRows').innerHTML='<div class="pathspace-row head"><span>Direction</span><span>Peer</span><span>Role</span><span>Application</span><span>Protocol</span><span>Packets</span><span>Bytes</span><span>Anomalies</span></div>'+rels.map(rel=>`<div class="pathspace-row"><span>${esc(rel.direction||'—')}</span><span>${esc(rel.peer||'—')}</span><span>${esc(rel.peer_role||'—')}</span><span>${esc(rel.application||'—')}</span><span>${esc(rel.protocol||'—')}</span><span>${Number(rel.packets||0).toLocaleString()}</span><span>${Number(rel.bytes||0).toLocaleString()}</span><span class="${(rel.anomalies||[]).length?'pathspace-anomaly':''}">${(rel.anomalies||[]).length}</span></div>`).join('');}catch(error){P('pathRows').innerHTML=`<div class="pathspace-empty"><b>NO PATH CREATED</b><br>${esc(error.message)}</div>`;P('pathSummary').innerHTML='';P('pathTruth').textContent='No evidence-backed path report available.';P('pathMap').innerHTML='<div class="pathspace-empty">MON did not fabricate a path for this IP.</div>'}}
inject();
})();
</script>
"""
